export default function TasksRoute() {
  const query = useActionQuery("list-tasks", {});
  const create = useActionMutation("create-task");
  const complete = useActionMutation("complete-task");
  const [searchParams, setSearchParams] = useSearchParams();
  const taskId = searchParams.get("taskId");
  const [title, setTitle] = useState("");
  const [message, setMessage] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const detailRef = useRef<HTMLHeadingElement>(null);
  const selected = query.data?.find((task) => task.id === taskId);
  const selectionError = taskId && query.isSuccess && !selected;

  useEffect(() => {
    if (selected) {
      void writeClientAppState(`selection:${TAB_ID}`, { kind: "task", id: selected.id, title: selected.title }, { requestSource: TAB_ID });
      detailRef.current?.focus();
    } else {
      void deleteClientAppState(`selection:${TAB_ID}`, { requestSource: TAB_ID });
    }
    return () => { void deleteClientAppState(`selection:${TAB_ID}`, { requestSource: TAB_ID, keepalive: true }); };
  }, [selected?.id, selected?.title]);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setMessage("");
    try {
      const task = await create.mutateAsync({ title: title.trim() });
      setTitle("");
      setMessage("Tarefa criada.");
      setSearchParams({ taskId: task.id });
      inputRef.current?.focus();
    } catch { /* A mensagem da ação é exibida abaixo. */ }
  }

  async function toggle(id: string, completed: boolean) {
    setMessage("");
    try {
      await complete.mutateAsync({ id, completed });
      setMessage(completed ? "Tarefa concluída." : "Tarefa reaberta.");
    } catch { /* A mensagem da ação é exibida abaixo. */ }
  }

  const error = create.error ?? complete.error;
  return (
    <section className="mx-auto w-full max-w-3xl space-y-6 p-4 sm:p-8" aria-label="Tarefas">
      <form onSubmit={submit} className="space-y-2">
        <Label htmlFor="task-title">Nova Tarefa</Label>
        <div className="flex flex-col gap-2 sm:flex-row">
          <Input ref={inputRef} id="task-title" value={title} onChange={(event) => setTitle(event.target.value)} maxLength={240} required disabled={create.isPending} className="min-w-0 flex-1" />
          <Button type="submit" disabled={create.isPending || !title.trim()}>{create.isPending ? "Criando…" : "Criar Tarefa"}</Button>
        </div>
      </form>
      <p role="status" aria-live="polite" className="text-sm">{message}</p>
      {error ? <p role="alert" className="text-sm text-destructive">{actionErrorMessage(error) ?? "Não foi possível salvar. Tente novamente."}</p> : null}
      {query.isPending ? <p role="status">Carregando tarefas…</p> : query.isError ? <div role="alert" className="space-y-2"><p>{actionErrorMessage(query.error) ?? "Não foi possível carregar as tarefas."}</p><Button variant="outline" onClick={() => void query.refetch()}>Tentar Novamente</Button></div> : query.data?.length === 0 ? <p className="text-muted-foreground">Você ainda não tem tarefas.</p> : (
        <ul className="divide-y rounded-lg border" aria-label="Lista de Tarefas" aria-busy={query.isFetching}>
          {query.data?.map((task) => <li key={task.id} className="flex min-w-0 items-center gap-3 p-3">
            <input type="checkbox" checked={task.completed} disabled={complete.isPending} onChange={(event) => void toggle(task.id, event.target.checked)} aria-label={`Concluir ${task.title}`} className="size-5 shrink-0 accent-primary focus-visible:ring-2" />
            <button type="button" onClick={() => setSearchParams({ taskId: task.id })} aria-current={taskId === task.id ? "true" : undefined} className={`min-h-11 min-w-0 flex-1 rounded px-2 text-left break-words focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${task.completed ? "text-muted-foreground line-through" : ""}`}>{task.title}</button>
          </li>)}
        </ul>
      )}
      {selectionError ? <p role="alert">Tarefa não encontrada ou indisponível para sua conta.</p> : null}
      {selected ? <article className="space-y-3 rounded-lg border p-4" aria-label="Tarefa Aberta">
        <h2 ref={detailRef} tabIndex={-1} className="break-words text-lg font-semibold focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">{selected.title}</h2>
        <p>{selected.completed ? "Concluída" : "Pendente"}</p>
        <Button variant="outline" onClick={() => setSearchParams({})}>Fechar Tarefa</Button>
      </article> : null}
    </section>
  );
}

