import { boolean, index, pgTable, text, timestamp } from "drizzle-orm/pg-core";

export const tasks = pgTable("tasks", {
  id: text("id").primaryKey(),
  ownerEmail: text("owner_email").notNull(),
  title: text("title").notNull(),
  completed: boolean("completed").notNull().default(false),
  createdAt: timestamp("created_at", { withTimezone: true, mode: "string" }).notNull().defaultNow(),
}, (table) => [index("tasks_owner_created_idx").on(table.ownerEmail, table.createdAt)]);

import { fail, type ActionRunContext } from "@agent-native/core/action";
import { and, desc, eq } from "drizzle-orm";
import { getDb } from "./index.js";
import { tasks } from "./schema.js";

export function requireTaskOwner(context?: ActionRunContext): string {
  const email = context?.userEmail?.trim().toLowerCase();
  if (!email) fail("Entre na sua conta para acessar tarefas.", { statusCode: 401, errorCode: "unauthenticated" });
  return email;
}

const taskFields = { id: tasks.id, title: tasks.title, completed: tasks.completed, createdAt: tasks.createdAt };

export async function listTasks(ownerEmail: string) {
  return getDb().select(taskFields).from(tasks).where(eq(tasks.ownerEmail, ownerEmail)).orderBy(desc(tasks.createdAt), desc(tasks.id));
}

export async function getTask(ownerEmail: string, id: string) {
  const [task] = await getDb().select(taskFields).from(tasks).where(and(eq(tasks.ownerEmail, ownerEmail), eq(tasks.id, id)));
  if (!task) fail("Tarefa não encontrada.", { statusCode: 404, errorCode: "not_found" });
  return task;
}

