describe("private tasks", () => {
  it("rejects anonymous reads and writes", async () => {
    await expect(listTasks.run({}, { caller: "frontend" })).rejects.toThrow("Entre na sua conta");
    await expect(createTask.run({ title: "Anonymous" }, { caller: "tool" })).rejects.toThrow("Entre na sua conta");
    await expect(completeTask.run({ id: crypto.randomUUID(), completed: true }, { caller: "frontend" })).rejects.toThrow("Entre na sua conta");
  });
  it("validates empty and oversized input", async () => {
    await expect(createTask.run({ title: "   " }, owner)).rejects.toThrow();
    await expect(createTask.run({ title: "a".repeat(241) }, owner)).rejects.toThrow();
  });
  it("authorizes deep-link navigation and current screen reads", async () => {
    const task = await createTask.run({ title: "Open target" }, owner);
    state.navigation = { view: "tasks", taskId: task.id };
    expect((await viewScreen.run({}, owner)).openTask).toMatchObject({ id: task.id });
    await expect(viewScreen.run({}, other)).rejects.toThrow("Tarefa não encontrada");
    await expect(navigate.run({ view: "tasks", taskId: task.id }, other)).rejects.toThrow("Tarefa não encontrada");
    expect(state.write).not.toHaveBeenCalled();
    await navigate.run({ view: "tasks", taskId: task.id }, owner);
    expect(state.write).toHaveBeenCalledTimes(1);
