    state.navigation = { view: "home" };
    expect(await viewScreen.run({}, owner)).not.toHaveProperty("openTask");
  });
  it("persists, isolates ownership and completes using the same shared actions", async () => {
    const task = await createTask.run({ title: "Review" }, owner);
    expect(task._receipt.verified).toBe(true);
    expect(await listTasks.run({}, other)).toEqual([]);
    await expect(completeTask.run({ id: task.id, completed: true }, other)).rejects.toThrow("Tarefa não encontrada");
